// v09.3 nach Gegenprüfung E: Zeile zu Gedankenstrichen eindeutig gefasst (Ersetzen statt Weglassen), Satz zu ein und eine gekuerzt.
// v09.3 (19.11.2026): neue Zeile zu Gedankenstrichen, Auslassungspunkten und Absaetzen im Korrekturabschnitt.
// Zweck: Prompt für die Neufassung bauen (v09): der ursprüngliche Prompt plus ein Korrekturabschnitt mit den gefundenen Wörtern.
// Warum: das Modell soll genau wissen, welche Wörter das Zahlenverbot verletzt haben, und die Pflichtangabe aus dem Briefing nennen. Der Korrekturabschnitt ist Anweisung des Workflows, das Briefing bleibt Material.
const pr = $('Prompt bauen [Code]').first().json;
const k = $input.first().json;
const fund = (Array.isArray(k.zahlen_fund) ? k.zahlen_fund : []).map(x => String(x).slice(0, 40)).slice(0, 8);
const fehlt = (Array.isArray(k.fehlende_angaben) ? k.fehlende_angaben : []).map(x => String(x).slice(0, 40)).slice(0, 4);
const liLang = Math.round(Number(k.li_zu_lang)) || 0;
const liRoh = Math.round(Number(k.li_roh)) || 0;
const zahlenGrund = fund.length > 0 || fehlt.length > 0 || (Array.isArray(k.fehlend_gekuerzt) && k.fehlend_gekuerzt.length > 0);
const teile = ['## Korrektur zur ersten Fassung'];
if (zahlenGrund || !liLang) teile.push('Der Auftrag verbietet Zahlen und Zahlwörter, die nicht im Briefing stehen.');
if (fund.length) teile.push('Deine erste Fassung enthielt: ' + fund.join(', ') + '. Schreibe alle Texte noch einmal und lasse diese Wörter weg.');
if (zahlenGrund || !liLang) teile.push('Das Verbot gilt auch für Ordnungszahlen (erste, zweite, dritte), Bruchwörter (halb, Hälfte, Viertel) und Zeitangaben ohne Zahl (Tage, Stunden). Formuliere dann allgemein (kurz, schnell, oft, am Anfang). Erlaubt sind nur Zahlen und Wörter, die im Briefing stehen.');
if (fehlt.length) teile.push('Nenne diese Angabe aus dem Briefing wörtlich, mit Zahl und Einheit zusammen, in mindestens einem Text: ' + fehlt.join(', ') + '.');
const gek = (Array.isArray(k.fehlend_gekuerzt) ? k.fehlend_gekuerzt : []).map(x => String(x).slice(0, 40)).slice(0, 4);
// Warum eigener Hinweis: stand die Angabe in der ersten Fassung hinter der Längengrenze, wurde sie abgeschnitten. Dann hilft nur kürzer schreiben und die Angabe früh nennen.
if (gek.length) teile.push('In deiner ersten Fassung stand ' + gek.join(', ') + ' erst hinter der Längengrenze und wurde deshalb abgeschnitten. Halte die Grenzen ein (caption_instagram höchstens 1800 Zeichen, linkedin_post höchstens 900 Zeichen, Folientext höchstens 220 Zeichen) und nenne die Angabe früh, zum Beispiel in der ersten Folie oder im ersten Satz.');
if (liLang) teile.push((liRoh && liRoh === liLang ? 'Dein linkedin_post hat ' : (liRoh ? 'Dein linkedin_post hatte ' + liRoh + ' Zeichen, nach dem Weglassen ganzer Sätze noch ' : 'Dein linkedin_post hat nach dem Weglassen ganzer Sätze noch ')) + liLang + ' Zeichen, erlaubt sind höchstens 900. Schreibe ihn noch einmal kürzer, Ziel unter 900 Zeichen: weniger und kürzere Sätze. Kürze nie mitten im Satz. Der erste Satz jedes Absatzes außer im letzten Absatz, der letzte Satz, Sätze mit Zahlen aus dem Briefing, Sätze mit einer Verneinung oder Einschränkung (nicht, nichts, kein, nie, niemals, nur, aber, jedoch, allerdings, sondern, außer, ohne, höchstens, mindestens, erst, niemand, kaum, lediglich, ausschließlich, weder, bloß, nirgends), jeder Absatz mit einem solchen Satz und jeder Absatz mit einem Satz, der mit Aber, Doch, Jedoch, Allerdings, Sondern, Nur oder Außer beginnt, bleiben dem Sinn nach vollständig erhalten; fasse sie kürzer, statt Sätze daraus wegzulassen. Auch der Absatz direkt vor einem solchen Absatz bleibt dem Sinn nach vollständig erhalten. Alle anderen Sätze darfst du weglassen.');
teile.push('Ersetze jeden Gedankenstrich durch ein Komma, einen Punkt oder einen Doppelpunkt. Kommas, Punkte und Fragezeichen setzt du wie gewohnt. Schreibe keine Auslassungspunkte. Der LinkedIn-Post behält 5 bis 6 Absätze mit einer Leerzeile dazwischen; kürze lieber die einzelnen Absätze, statt Absätze wegzulassen.');
teile.push('Antworte wieder nur mit dem JSON-Objekt.');
return [{ json: { system: pr.system, user: pr.user + '\n\n' + teile.join('\n') } }];
